import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Empacotamento, assinatura e registros de plugins","description":"","frontmatter":{"title":"Empacotamento, assinatura e registros de plugins","docId":"developer.plugins.packaging-registry","translationKey":"developer.plugins.packaging-registry","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4621be5493f2518bff00b4330fcf781ac016761ed8549c118515d6c212fc56cf","translationRevision":"deea78ac45747c2e51f8529936d1db6df6772c26e9d736c6735288587623ac9b","order":280},"headers":[],"relativePath":"pt/developer/plugins/packaging-registry.md","filePath":"pt/developer/plugins/packaging-registry.md","lastUpdated":1795735295000}`),a={name:`pt/developer/plugins/packaging-registry.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="plugin-packaging-signing-and-registries" tabindex="-1">Empacotamento, assinatura e registros de plugins <a class="header-anchor" href="#plugin-packaging-signing-and-registries" aria-label="Permalink to “Empacotamento, assinatura e registros de plugins”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Distribua um pacote cujos bytes, autoridade do publicador e compatibilidade com o host possam ser verificados independentemente. Comece com um plugin validado e um destino compatível. A assinatura precisa de chaves privadas de autor mantidas fora do repositório; delegação da raiz do registro é responsabilidade separada do operador.</p><h2 id="prepare-a-reviewable-archive" tabindex="-1">Prepare um arquivo revisável <a class="header-anchor" href="#prepare-a-reviewable-archive" aria-label="Permalink to “Prepare um arquivo revisável”">​</a></h2><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publisher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys</span></span></code></pre></div><p><code>build</code> compila o pacote e cria arquivos <code>.plugin</code>. Entrada do manifesto, recursos, idiomas, saída da interface e dependências relevantes do runtime são incluídos com <code>checksums.json</code>. Compilações nativas/de processo precisam de um artefato de destino compatível; pacotes apenas JavaScript continuam portáteis até que addons nativos ou funcionalidades da plataforma os restrinjam.</p><p>Para um arquivo já compilado, use caminhos exatos em vez de um curinga não revisado:</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.key.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span></span></code></pre></div><p>Substitua o nome do arquivo pela saída real específica do destino da compilação. A assinatura cobre as somas de verificação, que cobrem os arquivos do pacote. Chaves públicas podem ser compartilhadas; arquivos de chaves privadas não devem entrar no controle de versão nem em registros.</p><h2 id="trust-and-update-policy" tabindex="-1">Política de confiança e atualização <a class="header-anchor" href="#trust-and-update-policy" aria-label="Permalink to “Política de confiança e atualização”">​</a></h2><p>O protocolo de registro estático tem autoridade assinada pela raiz e chaves delegadas de índice/publicador. Aprovação do namespace do publicador não é o mesmo que integridade de pacote, e um resumo do catálogo do Cloud não pode substituir nenhuma das cadeias de assinatura. O resolvedor verifica canal, mecanismo, esquema/protocolo/ABI, runtime e destino. Versões retiradas, revogadas ou incompatíveis continuam inelegíveis mesmo quando o hash do arquivo corresponde.</p><p>A instalação no host apresenta primeiro uma revisão. Atualizações automáticas exigem política permitida, pacote sem versão fixada, publicador assinado compatível e nenhuma nova autoridade; permissões ampliadas exigem revisão. A instalação pelo catálogo Cloud do produto é distinta da autoria de registro estático de baixo nível, e fluxos comuns do produto rejeitam URLs remotas arbitrárias de pacotes.</p><h2 id="expected-result-recovery-and-verification" tabindex="-1">Resultado esperado, recuperação e verificação <a class="header-anchor" href="#expected-result-recovery-and-verification" aria-label="Permalink to “Resultado esperado, recuperação e verificação”">​</a></h2><p>O instalador pode verificar bytes antes de aplicar um pacote revisado e manter estado de reversão/recuperação. A preparação de desenvolvimento fica fora do gerenciamento do instalador. Em falha de confiança, corrija delegação ou metadados do publicador em vez de usar flags para ignorar assinaturas como política normal de distribuição. Em inicialização incerta do runtime, pare a substituição e reconcilie o resultado mantido.</p><p>Use <code>bun scripts/task.ts rust test -p tiktools-plugin-package --locked</code> e os testes de registro para dados de teste offline. O <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-package/src" target="_blank" rel="noreferrer">verificador de pacotes</a> e o <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-plugin-registry/src/model.rs" target="_blank" rel="noreferrer">modelo de registro</a> definem os formatos técnicos; a infraestrutura de publicação precisa de aceitação separada pelo operador.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalhes de operação”">​</a></h2><p>Interprete o JSON da verificação, não apenas o código de saída. <code>verify</code> pode terminar com sucesso e <code>signature.status</code> igual a <code>unsigned</code> ou <code>untrusted</code>. Aceite somente <code>verified</code> com ID do pacote, editor e chave esperados e confira a política de distribuição. Uma chave local <code>--trust</code> comprova essa assinatura, não delegação do registro ou aprovação do namespace. Checksums isolados não comprovam autoridade nem confiança do updater. A automação abaixo deve falhar diante de resultado inesperado.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verification.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;const r = await Bun.file(&quot;verification.json&quot;).json(); if (r.signature?.status !== &quot;verified&quot; || r.id !== &quot;acme.hello&quot; || r.signature.publisher !== &quot;acme&quot; || r.signature.keyId !== &quot;acme-1&quot;) throw new Error(&quot;Package trust did not match policy&quot;);&#39;</span></span></code></pre></div><h2 id="command-line-operations" tabindex="-1">Operações de linha de comando <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operações de linha de comando”">​</a></h2><p>Cada operação deste guia também está disponível na CLI — offline, scriptável e apta para agentes. As linhas de uso são sintaxe do parser e permanecem em inglês em todos os idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools publisher list</code></td><td>listar os namespaces de publicador</td></tr><tr><td><code>tiktools publisher create &lt;namespace&gt;</code></td><td>criar um namespace de publicador</td></tr><tr><td><code>tiktools publisher delete &lt;namespace-or-publisher-id&gt;</code></td><td>excluir um namespace ou publicador <strong>destrutivo</strong></td></tr><tr><td><code>tiktools publisher keys &lt;publisher-id&gt;</code></td><td>listar as chaves de assinatura de um publicador</td></tr><tr><td><code>tiktools publisher enroll &lt;publisher-id&gt; [--key-id &lt;id&gt;]</code></td><td>inscrever uma chave de publicador; lê a senha do backend a partir de stdin</td></tr><tr><td><code>tiktools publisher upload &lt;publisher-id&gt; &lt;path&gt;</code></td><td>enviar um pacote de plugin</td></tr><tr><td><code>tiktools publisher submit &lt;upload-id&gt; &lt;publisher-key-id&gt; &lt;plugin-id&gt; &lt;version&gt; [--target any]</code></td><td>submeter um envio para revisão</td></tr><tr><td><code>tiktools publisher release &lt;release-id&gt;</code></td><td>criar uma release</td></tr><tr><td><code>tiktools publisher publish &lt;release-id&gt;</code></td><td>publicar uma release</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>listar os registros configurados</td></tr><tr><td><code>tiktools registry refresh</code></td><td>atualizar os metadados do registro</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>mostrar um pacote do registro</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>buscar no catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>página de resumos do catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versões de um pacote do catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>capacidades de paginação do catálogo cloud</td></tr><tr><td><code>tiktools registry defaults</code></td><td>configuração padrão do registro</td></tr></tbody></table><p>Consulte a <a href="./../cli.html">referência completa de comandos</a> para as convenções, a saída JSON e os marcadores de operações destrutivas.</p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};